} from '../src/fixture/angular-pigallery2-migration-record.ts';
import { ANGULAR_16_ECOSYSTEM_PACKAGES } from '../../frameworks/angular/src/index.ts';

async function readAttempt(): Promise<Record<string, unknown>> {
